  end if;
  if (select count(*) from auth.users) < 120 then
    raise exception 'STOPPED: run part 1 (members) first. Nothing was changed.';
  end if;
  if exists (select 1 from public.forum_posts) or exists (select 1 from public.forum_replies) then
    raise exception 'STOPPED: the forum already has content. Run 0-reset-optional.sql to start over. Nothing was changed.';
  end if;
end $$;

insert into public.forum_posts (id, user_id, author_name, category, title, body, created_at)
select v.id::uuid, v.user_id::uuid, v.author_name, v.category, v.title, v.body, now() - make_interval(mins => v.mins)
from (values
  ('e8b69d53-950e-531f-a74d-8955f7528eb6', '4d9afb4d-15fd-5435-a9d8-73d487330d10', 'Adrian Brennan', 'introductions', 'Hi, I walk dogs for a living', 'Not a dog parent but I walk a lot of them in Willow Canyon. Looking to meet more of the community.', 2694),
  ('8d3789a5-e26a-5bcf-aa67-1889c64c30b8', '4eeb9202-ddf0-517e-a4c6-1b256820e98a', 'Hollis Jessup', 'training-behavior', 'Leash reactivity, where do I start?', 'Atlas lunges at other dogs on walks. He is friendly, just overexcited. We have been avoiding the park. Tips?', 6090),
  ('af9c9f54-e93f-5290-a02c-a055daec2d1c', '2a3beb8e-5673-5838-a965-c188b5349094', 'Ulises Sandoval-Reyes', 'show-off', 'Rescue anniversary', 'One year ago today Penny came home with a blanket and a bad attitude. She is now my best friend.', 7262),
  ('5a7127e8-0fd1-5119-a21c-b6e324bc6364', '489441f5-1432-5bb7-ae7b-dd7bdcfa73d9', 'Owen Dunmore', 'local-spots', 'Where do you board when you travel?', 'Heading out of town for a week. Where do you leave your dog?', 8600),
  ('7dc85d63-9075-5a59-a1be-7b7a9f9ae4fd', 'ed28bd2c-44b8-5291-af5b-3c9b8fd532f4', 'Felix Zimmerman', 'introductions', 'Hi from Mesa Verde, meet Biscuit', 'Just joined! Biscuit is a two year old French bulldog who thinks every stranger is a long lost friend. Looking for morning walk buddies and a vet recommendation.', 9881),
  ('f68ce6cd-d107-52fb-ad5d-92fd7594b1a0', 'f4d134ab-b893-5632-a1e8-5419eef91570', 'Yosef Fairbanks', 'events-meetups', 'Trail clean up day', 'Organizing a trash pickup on the Arroyo Trail next month. Gloves and bags provided.', 10924),
  ('86f3fba0-d789-51f6-a126-2d1a766a2d5f', '83c110c7-b126-5c53-a14e-e3da2686e49a', 'Tobias Thackeray', 'training-behavior', 'Separation anxiety after the holidays', 'Back to the office and Hank howls the whole time. Camera shows he calms down after about 40 minutes. What helps?', 13989),
  ('af0a7ba8-4be4-5ba8-a815-46e9ca0274d4', '270415b9-175a-5292-ab7d-c85c7da5dc90', 'Felix Iverson', 'health-wellness', 'Signs of heat stress to watch for', 'Scared myself yesterday when Pepper started heavy panting and drooling on a short walk. Wrote down what the vet told me in case it helps someone.', 15092),
  ('5d643ae4-1651-5f2c-a4a3-82c70b4fd8ec', '8fd25799-6d65-50ba-ad54-bda1ebb2f790', 'Tamsin Whitlock', 'introductions', 'Just adopted a senior pup', 'Olive is ten and slow and perfect. Looking for gentle walking routes and a vet who is good with seniors.', 17935),
  ('a046971b-bf7e-56cd-aacf-638114eea161', '2a37c360-fa27-5717-ab79-49ca6871975a', 'Felix Yarrow', 'local-spots', 'Best shaded walking routes', 'Looking for walks that are actually shaded in summer. We are in Cactus Flats.', 18390),
  ('b86b525a-ea0d-544c-a076-61814d68a2c2', '4c8ec47f-ede4-5d2f-a8fa-5bc73f6e4b2f', 'Pierce Zimmerman', 'travel', 'Road trip with a dog', 'Planning a long drive with Sage. Tips for breaks, water and keeping a dog calm?', 20666),
  ('a82a2fd5-5356-5935-a4ac-7f233765de5a', '8fd25799-6d65-50ba-ad54-bda1ebb2f790', 'Tamsin Whitlock', 'introductions', 'Foster fail, party of one', 'I fostered Waffles for two weeks. That was eight months ago. He is officially mine and officially in charge.', 21891),
  ('e15ada83-4312-5714-a764-8e76b0fbf596', '5aa61ba4-8418-5c99-afe3-e995b9b1fb0e', 'Zane Whitlock', 'introductions', 'New to Desert Springs with a rescue greyhound', 'Moved here last month with Juniper, a retired racer who is learning what a couch is. Any tips for a dog who has never seen a sliding glass door?', 23945),
  ('d6009930-9c59-51a7-aaa1-a6ed1472e29d', 'bc5de188-b85d-587b-a436-237c6e226ef8', 'Rowan Garrity', 'health-wellness', 'Vaccines and boarding requirements', 'Reading up on boarding and every place wants something different. Is there a standard list people follow?', 25070),
  ('45bf6171-1668-5f6e-ad6d-c3187444f3d3', '1107b92b-b953-51cc-a35a-6d1fcba0972f', 'Priya Norwood', 'nutrition-food', 'Kibble vs fresh food', 'Thinking of switching Daisy to a fresh food subscription. Anyone made the jump?', 28504),
  ('c00ec036-a14c-58e4-a9bb-bcc0fa0d3ce0', '65268122-3626-56ee-a515-a204146ac710', 'Elias Lockridge', 'show-off', 'Bandana collection update', 'Otis now has a bandana for every season. This is the Halloween edition.', 29096),
  ('a41012b6-f193-51f4-ad5a-1c8e985c9fa6', 'c1377c14-8ae3-5b30-a421-7bcf2466d6d9', 'Jasper Calloway', 'local-spots', 'Late night vet options', 'Had a scare last night and was glad I knew where the ER was. Posting here so more people know the options.', 30954),
  ('790e306a-174d-537d-add7-02635044ef30', 'bc5de188-b85d-587b-a436-237c6e226ef8', 'Rowan Garrity', 'introductions', 'Introducing Moose, 90 pounds of gentle', 'Moose is a Great Pyrenees mix and has never knowingly met a squirrel he disliked. Hoping to find other big dog people nearby.', 32244),
  ('4bd94332-b7ec-5857-ab02-11d828f5c484', 'e5bf9ca6-d33e-5f26-a526-8ce7baac6409', 'Ivan Dunmore', 'training-behavior', 'Puppy biting phase, please send hope', 'Fig is fourteen weeks and my hands look like I lost a fight with a rosebush.', 35430),
  ('ec5d1d4e-8e1f-51ca-a7d5-a44a538ee252', 'ecd816bb-0ee1-507f-a937-84d856cc1d90', 'Silas Sandoval-Reyes', 'nutrition-food', 'Homemade frozen treats for the heat', 'Pupsicles are a hit here. Sharing my favorite recipe, two ingredients: plain yogurt and mashed banana. Freeze in a silicone tray.', 36390),
  ('44f57240-9c58-585e-a429-2d39ad7a8ff8', 'dccb82fe-7cc9-5040-aed3-6e72da765dbc', 'Rowan Dunmore', 'events-meetups', 'Puppy playdate for under 6 months', 'Looking to start a small puppy social for pups still getting vaccinated. Anyone interested?', 39194),
  ('8bd95fa4-8d0d-58da-a409-42806d58c49c', '78f363e8-3005-5ac6-a438-21a39386d4ea', 'Priya Garrity', 'health-wellness', 'Foxtails in ears and paws', 'Found one in Rocket paw after the trail. Anyone have a go-to routine for checking after hikes?', 41360),
  ('e2ac1555-0d25-5a38-a1df-b4025fddceb4', '7c489f09-b737-5f9f-ac87-3bb996ebb508', 'Kellan Underhill', 'events-meetups', 'Yappy hour planning thread', 'Thinking about a monthly yappy hour at a dog friendly patio. What nights work for people?', 42885),
  ('7a8572cc-58c1-5d55-a114-cd55926f2a27', 'de2ac23a-1b38-57f1-a711-c25cbaeea4b6', 'Tamsin Holloway', 'local-spots', 'Groomers who are patient with anxious dogs', 'Looking for a groomer who takes it slow. Ziggy gets stressed at the dryer.', 45439),
  ('58816185-7598-5f3b-aadd-c6d8af605bff', '4635e545-fc93-5f72-a158-4b988037e4dc', 'Lucas Underhill', 'health-wellness', 'Tick and flea prevention in the desert', 'Is flea and tick prevention needed year round here? Getting mixed answers.', 47014),
  ('2021fb7b-88c2-555c-ad77-47b59376fddf', 'a358bb84-9945-558b-a2fb-92a485681343', 'Xavier Oakes', 'training-behavior', 'Tricks to keep a smart dog busy', 'Border collie mix with way too much energy. Beyond fetch, what mental games do you do?', 47220),
  ('264a5959-4813-5701-abfa-a5e64e3f5f78', '5aa61ba4-8418-5c99-afe3-e995b9b1fb0e', 'Zane Whitlock', 'health-wellness', 'Dental care that actually works', 'Our vet says Maple needs a cleaning. Before I book it, what do you do to keep teeth good between visits?', 49960),
  ('f3763ce1-51f2-5d9b-af57-01219ef1ed52', '67bf4511-263d-5623-a55f-6bdc2d593c0b', 'Dario Vasquez-Lin', 'show-off', 'Dog and cactus, a cautionary tale', 'Rocket got too close to a cholla this morning. All fine now but that was a long hour with tweezers.', 50965),
  ('15856a59-ed37-528f-a213-1a38cff2a5c8', 'c864dfd7-c8fe-58d5-a256-501e7286aa9b', 'Lucas Calloway', 'health-wellness', 'Anyone dealing with allergies?', 'Gus has been licking his paws raw this spring. Vet says environmental allergies. What has helped your dog?', 52239),
  ('d3f9ac99-5ce9-59ed-af53-eddcfbc53fe8', '6afdb284-6fe5-5784-a571-7999ebc50bca', 'Tamsin Underhill', 'events-meetups', 'Sunday morning walk, who is in?', 'Organizing a casual walk at Cactus Flats Dog Park this Sunday at 8am. All sizes welcome.', 56149),
  ('e926ae47-0796-58dd-a158-08ce6abb5c27', 'c6328630-652d-5b81-a9dd-2f78d2f6416c', 'Dario Holloway', 'travel', 'Flying with a small dog', 'First flight with Taco coming up. In cabin carrier. Anything I should know?', 56013),
  ('12eaa69b-99b3-5e21-ab6c-90f491bdff7a', '86032013-39a9-5639-ad01-f5a470e4a28c', 'Hollis Pemberton', 'training-behavior', 'Barking at the doorbell', 'Penny goes nuts every time a delivery arrives. I have tried a lot of things. What actually stopped it for you?', 57285),
  ('7bf5461e-8e28-5b38-aec6-669236a64152', '0a02ea2a-a699-558a-a5ef-bf6eff6c0d0e', 'Beckett Fairbanks', 'nutrition-food', 'Slow feeders and bloat', 'Rue gobbles dinner in 20 seconds. Slow feeder or puzzle bowl, which worked for you?', 61368),
  ('6667357e-edbc-5b32-a85e-46bd39f6cc33', 'f4d134ab-b893-5632-a1e8-5419eef91570', 'Yosef Fairbanks', 'health-wellness', 'How hot is too hot for walks?', 'It is 104 this week. I walk before 6am but the ground is still warm. What is your cutoff for pavement?', 63126),
  ('7d84c461-ab05-59dd-aa14-5aa1fb04503b', '2d2eab0f-4921-5222-a569-102097e74664', 'Jasper Vasquez-Lin', 'local-spots', 'Dog-friendly patios, summer edition', 'Which patios have misters and water bowls? We are tired of sweating through brunch.', 63530),
  ('39826457-215a-5dd4-a46a-8bc329288502', '8d82b7ee-49b9-5595-a611-4fa8bc7d82e2', 'Priya Alder', 'training-behavior', 'Loose leash walking drills', 'My arm is getting a workout. Any drills that helped you go from pulling to a calm walk?', 67110),
  ('a44c0410-fc9e-541e-af5f-5adb18c2f3b3', 'a9d05ca1-8c46-5b02-a2ed-c00df004a892', 'Gavin Quill', 'training-behavior', 'Recall tips that worked for us', 'Took six months but Clover now comes when called in the park. Sharing what worked for us in case it saves you time.', 68604),
  ('75f064d9-7c41-5db1-a877-d18901abb232', '503a934d-7133-5d9b-add1-8e10df23eab1', 'Tobias Vasquez-Lin', 'travel', 'Camping with the pack', 'First camping trip with two dogs. What do I need to bring that I will forget?', 70823),
  ('ff57c3a7-a608-5de3-a6ff-0ec28192598a', 'c53c8a74-6101-5543-a29b-88337f5f1935', 'Silas Calloway', 'events-meetups', 'Volunteering at the humane society', 'Desert Springs Humane Society is looking for dog walkers on weekends. Anyone want to go together?', 70374),
  ('5f50f60b-1cea-5368-a971-862213bfc1d4', 'ebd328f1-5a5a-5f26-aac6-90aa734895ac', 'Marisol Kirkland', 'introductions', 'Hello! Two corgis and a lot of hair', 'Name is Dario, I live in Oasis Park with Tango and Mochi. If you see an orange fur tornado, that is us.', 74367),
  ('48506421-2c31-589f-a06f-96de2cd037e6', '26712ea6-eca3-58ed-a317-925d0db0748c', 'Nolan Brennan', 'travel', 'Dog-friendly hotels, mountains edition', 'Looking for a cabin with a fenced yard within a few hours of Desert Springs. Recommendations?', 74102),
  ('3d07c9d9-e07c-5ec9-a2ee-dfa346892fd7', '2be97f94-7094-5319-a7ad-6a5b5a139ab2', 'Silas Fairbanks', 'nutrition-food', 'Weight management for Labs', 'Gus is five pounds over his ideal. Vet suggested cutting back but he gives me the eyes.', 77247),
  ('47f5fae6-b3b2-5a00-a4b7-387512c8db6b', '21fd2f9c-20ac-5fb8-a9d8-2362cb2e5859', 'Jasper Kirkland', 'show-off', 'Sunrise walk selfie', 'Caught Juniper in the golden light this morning. She looks like a painting.', 77048),
  ('32fa4438-2a28-5f0e-aac2-b511a3ee3380', '4a422b50-bb58-5d29-af16-61a17f8be9e1', 'Elias Pemberton', 'events-meetups', 'Adoption day volunteers needed', 'Looking for help with an adoption event next weekend, setup crew and greeters.', 80253),
  ('c2dfc2f4-cd49-5d99-a043-300d9abb8aa1', '2ff8d17a-0e63-5bdf-a94f-362b8065e168', 'Vance Norwood', 'nutrition-food', 'Treats under ten calories', 'Trying to train Pretzel without ballooning him. Treat ideas that are small and low cal?', 83039),
  ('b4fc23ef-7bf9-5552-a12a-827233126296', '503a934d-7133-5d9b-add1-8e10df23eab1', 'Tobias Vasquez-Lin', 'local-spots', 'Cactus Flats Dog Park, anyone been?', 'Heard the new small dog area opened. Worth the drive?', 83306),
  ('adf2e590-789e-59d5-a31b-28ba62fcc062', 'c20c7593-8307-57df-a61f-5b91972ade0d', 'Lucas Alder', 'local-spots', 'Pet supply stores worth supporting', 'Looking to shop local for dog food and toys. Who do you like?', 85445),
  ('6716a5b2-ed3b-5f55-acd0-44e018ced34b', '69da0ec1-bb5d-5f96-accc-624a7a3bebed', 'Zane Sandoval-Reyes', 'show-off', 'Pool day for the pack', 'First time Pretzel and Mochi have tried the pool. Mochi lasted three seconds before demanding a towel.', 86061)
) as v(id, user_id, author_name, category, title, body, mins);

insert into public.forum_replies (id, post_id, user_id, author_name, body, created_at)
