from (values
  ('9248ac14-9a53-5795-a865-9624cccbd563', 'e8b69d53-950e-531f-a74d-8955f7528eb6', '5c0edbd6-b0b7-5e22-a081-66abdb91a3fc', 'Zane Oakes', 'Welcome! You probably know half our dogs already.', 2331),
  ('c8df41d3-33e9-532b-aecd-2e9eaf35b75f', 'e8b69d53-950e-531f-a74d-8955f7528eb6', '7476c5a8-99b2-583f-adbc-b9adf5112bc6', 'Pierce Ellery', 'Do you have openings? Several of us are looking.', 1850),
  ('5d4551ab-9d05-5e1d-a6a4-1de44891b783', 'e8b69d53-950e-531f-a74d-8955f7528eb6', '4d3c9907-16b6-530f-a0ec-968ec1fd700d', 'Zane Calloway', 'Thanks for all you do.', 942),
  ('42921ede-9c0c-53cd-afc8-c9bec7658382', 'e8b69d53-950e-531f-a74d-8955f7528eb6', 'ec3ab5a8-55fe-585e-a976-c9748eab484a', 'Wesley Kirkland', 'What a cutie, welcome!', 845),
  ('8711e9ab-1e92-5b91-a4a4-1d78c4b65c94', 'e8b69d53-950e-531f-a74d-8955f7528eb6', 'c9d639c8-8f70-5b33-a083-6bd1891afcbf', 'Noor Kirkland', 'Hope to see you at a walk soon.', 501),
  ('450bbc5d-dd15-5050-aa53-baae3901de25', '8d3789a5-e26a-5bcf-aa67-1889c64c30b8', 'c20c7593-8307-57df-a61f-5b91972ade0d', 'Lucas Alder', 'Distance is your friend. Start far enough away that he can still take treats, then close the gap slowly.', 5096),
  ('9bd7b950-ee08-51a7-a442-d83b6be735e5', '8d3789a5-e26a-5bcf-aa67-1889c64c30b8', '305ab6ed-e246-50c9-aa97-c82e3d448ddb', 'Noor Zimmerman', 'We did a reactive dog class and it changed everything. Highly recommend finding one with a small group.', 4043),
  ('f49ee7fe-5c47-5208-abbc-53984b9565a9', '8d3789a5-e26a-5bcf-aa67-1889c64c30b8', 'b8784225-ca1d-5c34-aca6-a6fac3413f9c', 'Priya Underhill', 'Practice u-turns and treats for looking at you before he sees the other dog.', 3064),
  ('343208f5-5112-57db-ae3d-24c51f9a506f', '8d3789a5-e26a-5bcf-aa67-1889c64c30b8', '0b8515c3-5e8e-520a-a16a-1f90312f4b3f', 'Priya Quill', 'We had the same issue, it does improve.', 2870),
  ('c1fa195d-ac77-5f29-adc5-8ec41aed798c', '8d3789a5-e26a-5bcf-aa67-1889c64c30b8', 'fba7eea5-7f37-5cdd-a655-19d4eaa42f71', 'Elias Brennan', 'Consistency is everything with this.', 2684),
  ('9ec86d00-e714-5e5e-ad82-f1067af793d1', 'af9c9f54-e93f-5290-a02c-a055daec2d1c', 'c49843ad-e95c-5e47-ad4a-5c9e88f4c5de', 'Ulises Rutherford', 'Happy gotcha day Penny!', 7043),
  ('f1eb9ff4-ade6-5434-aea8-15eb79d20883', 'af9c9f54-e93f-5290-a02c-a055daec2d1c', '6027f27d-64bc-5670-a382-3b62a45d6986', 'Ulises Iverson', 'Gave me goosebumps. Congratulations.', 5869),
  ('b4db996b-98c2-5659-aacb-9000ec1eb0b5', 'af9c9f54-e93f-5290-a02c-a055daec2d1c', 'a358bb84-9945-558b-a2fb-92a485681343', 'Xavier Oakes', 'What a glow up.', 4771),
  ('7048df26-6491-5612-aa24-a28eb1894e7d', 'af9c9f54-e93f-5290-a02c-a055daec2d1c', '1107b92b-b953-51cc-a35a-6d1fcba0972f', 'Priya Norwood', 'So cute!', 4522),
  ('8776d01c-592e-5af1-af70-40bb7592ab26', 'af9c9f54-e93f-5290-a02c-a055daec2d1c', 'bc5de188-b85d-587b-a436-237c6e226ef8', 'Rowan Garrity', 'Look at that face.', 4178),
  ('cc5ea3c4-21bf-5f98-a508-405c2a5aef19', '5a7127e8-0fd1-5119-a21c-b6e324bc6364', '68dc0be1-e32a-5989-afbc-8e1a5f9319cc', 'Dario Zimmerman', 'Mesa Meadows Pet Resort, our dog loves it.', 8368),
  ('db1c5052-c177-5433-a0ca-e00cfebbb5e7', '5a7127e8-0fd1-5119-a21c-b6e324bc6364', '8086ccd4-a242-55a7-a1bc-4506db49cc97', 'Ulises Dunmore', 'We use a sitter who stays at the house, easier on our guy.', 7817),
  ('cef93fef-476f-5f66-a64d-53c670e512cd', '5a7127e8-0fd1-5119-a21c-b6e324bc6364', '86032013-39a9-5639-ad01-f5a470e4a28c', 'Hollis Pemberton', 'Book early for holidays, boarding fills up fast.', 7216),
  ('766d9335-2603-5bb6-a8f9-e69ec19692c8', '5a7127e8-0fd1-5119-a21c-b6e324bc6364', '715a19ee-b563-5629-aa7b-bd3e144df68f', 'Nolan Vasquez-Lin', 'Thanks for the recommendation.', 6520),
  ('15370630-91c0-558c-a7cb-155a18e900e2', '5a7127e8-0fd1-5119-a21c-b6e324bc6364', '920fd3d6-3e59-52ce-a5d2-fe91a0268a99', 'Hollis Whitlock', 'We go there all the time.', 5823),
  ('0340efd2-fc66-5d88-a5b8-e252c033ee37', '7dc85d63-9075-5a59-a1be-7b7a9f9ae4fd', 'ecdc99a3-adf3-5e02-a6ec-0a00362827bb', 'Marisol Underhill', 'Welcome! Biscuit sounds like a delight. Mesa Verde Commons has a small-dog hour most mornings.', 8716),
  ('eed6b7cb-504e-5587-ad9a-4751e18d4f9b', '7dc85d63-9075-5a59-a1be-7b7a9f9ae4fd', '18e7ad9c-b9bb-565f-a410-3a5423d26f62', 'Ulises Yarrow', 'Same energy as my pug. You will love it here.', 7917),
  ('717bf53a-2934-57fb-a808-4fbe69fd58a2', '7dc85d63-9075-5a59-a1be-7b7a9f9ae4fd', '64357562-336b-58bb-af7e-bcd097c4f176', 'Xavier Sandoval-Reyes', 'Seconding the Commons, we are there around 7 most days.', 7111),
  ('456af656-f51d-5bba-a714-bc238ff1325d', '7dc85d63-9075-5a59-a1be-7b7a9f9ae4fd', 'dccb82fe-7cc9-5040-aed3-6e72da765dbc', 'Rowan Dunmore', 'Welcome to the community!', 6231),
